<?php
/**
 * =====================================================================
 *  AJIET STAFF CLUB — DIGITAL LOGO INAUGURATION
 *  Single-file PHP page (HTML + CSS + JS embedded)
 *  Click the curtain / the "Inaugurate" ribbon to reveal the club logo
 * =====================================================================
 */

// ---- Dynamic server-side data (PHP) ---------------------------------
date_default_timezone_set('Asia/Kolkata');
$eventTitle   = "AJIET Staff Club";
$eventTagline = "Connect | Collaborate | Celebrate";
$instituteName = "AJ Institute of Engineering and Technology";
$inaugDate    = date("jS F Y");
$inaugTime    = date("g:i A");
$dayName      = date("l");

// Simple visit counter (per-server run) stored in a text file, purely
// for a nice "Witnessed by N guests" live counter on the page.
$counterFile = __DIR__ . '/visit_count.txt';
$visits = 0;
if (file_exists($counterFile)) {
    $visits = (int) file_get_contents($counterFile);
}
$visits++;
@file_put_contents($counterFile, $visits);

// ---- Logo embedded as Base64 so the whole thing is ONE file ---------
$logoBase64 = "";
$logoSrc = "data:image/jpeg;base64," . $logoBase64;
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title><?php echo htmlspecialchars($eventTitle); ?> — Digital Logo Inauguration</title>
<style>
  :root{
    --gold:#e8c260;
    --gold-bright:#ffe9a8;
    --deep-red:#7a0f16;
    --deep-red-2:#5c0a10;
    --velvet-dark:#3d060b;
    --navy:#0a1030;
    --navy-2:#161c46;
    --cream:#fbf6ec;
    --blue:#233ea8;
    --green:#1c8a4b;
    --yellow:#f5b400;
    --red:#e3302e;
  }

  *{ box-sizing:border-box; margin:0; padding:0; }

  html,body{
    height:100%;
    overflow-x:hidden;
    font-family:'Georgia','Cambria',serif;
    background:var(--navy);
  }

  /* ================= STAGE BACKGROUND ================= */
  .stage{
    position:relative;
    min-height:100vh;
    width:100%;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:flex-start;
    overflow:hidden;
    background:
      radial-gradient(ellipse 120% 60% at 50% 0%, rgba(232,194,96,0.10), transparent 60%),
      radial-gradient(ellipse 80% 50% at 50% 100%, rgba(35,62,168,0.18), transparent 60%),
      linear-gradient(180deg, var(--navy) 0%, var(--navy-2) 45%, #0d1230 100%);
  }

  /* Floor sheen */
  .stage::after{
    content:"";
    position:absolute;
    left:0; right:0; bottom:0; height:38%;
    background:linear-gradient(180deg, transparent, rgba(0,0,0,0.55));
    pointer-events:none;
  }

  /* twinkling stars / dust */
  .sparkle-layer{
    position:absolute; inset:0; pointer-events:none; z-index:1;
  }
  .sparkle{
    position:absolute;
    width:3px; height:3px;
    background:var(--gold);
    border-radius:50%;
    opacity:.55;
    animation:twinkle 3.5s ease-in-out infinite;
  }
  @keyframes twinkle{
    0%,100%{ opacity:.15; transform:scale(1); }
    50%{ opacity:.9; transform:scale(1.8); }
  }

  /* ================= HEADER ================= */
  .header{
    position:relative;
    z-index:5;
    text-align:center;
    padding:34px 20px 10px;
    color:var(--cream);
  }
  .kicker{
    letter-spacing:6px;
    font-size:12.5px;
    text-transform:uppercase;
    color:var(--gold);
    font-family:'Trebuchet MS', sans-serif;
    font-weight:600;
    opacity:.9;
  }
  .main-title{
    margin-top:10px;
    font-size:clamp(28px, 5vw, 52px);
    font-weight:700;
    letter-spacing:2px;
    background:linear-gradient(180deg,#fff6da, var(--gold) 55%, #b6862a);
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
    text-shadow:0 2px 18px rgba(232,194,96,.25);
  }
  .sub-title{
    margin-top:8px;
    font-size:clamp(13px,2vw,17px);
    color:#cdd3ee;
    font-family:'Trebuchet MS', sans-serif;
    letter-spacing:.5px;
  }
  .divider{
    width:120px; height:2px; margin:16px auto 0;
    background:linear-gradient(90deg, transparent, var(--gold), transparent);
  }

  /* ================= THEATRE / CURTAIN AREA ================= */
  .theatre-wrap{
    position:relative;
    z-index:3;
    width:min(980px, 94vw);
    margin:26px auto 10px;
    aspect-ratio:16/10;
    border-radius:14px;
    overflow:hidden;
    box-shadow:
      0 0 0 10px #1a1330,
      0 0 0 13px rgba(232,194,96,.55),
      0 30px 70px rgba(0,0,0,.55);
    background:radial-gradient(ellipse at 50% 30%, rgba(255,255,255,.08), transparent 60%), #0b0a17;
  }

  /* spotlight cone that appears after reveal */
  .spotlight{
    position:absolute;
    top:-10%;
    left:50%;
    width:70%;
    height:130%;
    transform:translateX(-50%);
    background:radial-gradient(ellipse at 50% 0%, rgba(255,241,199,.35), rgba(255,241,199,0) 65%);
