    padding:20px;
    background:
      radial-gradient(circle at 50% 40%, rgba(232,194,96,.12), transparent 55%),
      repeating-linear-gradient(90deg, rgba(255,255,255,.02) 0 2px, transparent 2px 40px),
      #100c22;
  }

  .logo-frame{
    position:relative;
    width:min(46vw, 300px);
    aspect-ratio:1/1;
    border-radius:50%;
    padding:10px;
    background:
      conic-gradient(from 0deg, var(--gold), #fff3cf, var(--gold-bright), var(--gold));
    box-shadow:
      0 0 0 6px rgba(10,16,48,.9),
      0 0 60px 10px rgba(232,194,96,.45),
      0 25px 45px rgba(0,0,0,.5);
    transform:scale(.4);
    opacity:0;
    transition:transform 1s cubic-bezier(.2,1.4,.4,1) .5s, opacity .8s ease .5s;
  }
  .theatre-wrap.opened .logo-frame{
    transform:scale(1);
    opacity:1;
  }
  .logo-frame-inner{
    width:100%; height:100%; border-radius:50%;
    background:var(--cream);
    display:flex; align-items:center; justify-content:center;
    overflow:hidden;
  }
  .logo-frame-inner img{
