    object-fit:contain;
    border-radius:50%;
  }

  .reveal-caption{
    text-align:center;
    color:var(--cream);
    opacity:0;
    transform:translateY(14px);
    transition:opacity .8s ease 1.1s, transform .8s ease 1.1s;
  }
  .theatre-wrap.opened .reveal-caption{
    opacity:1; transform:translateY(0);
  }
  .reveal-caption .r-title{
    font-size:clamp(18px,3vw,26px);
    font-weight:700;
    letter-spacing:1px;
