    font-family:'Trebuchet MS', sans-serif;
    font-size:13px;
    letter-spacing:2px;
    text-transform:uppercase;
    color:#c9cfec;
  }

  /* ---- Curtains ---- */
  .curtain{
    position:absolute;
    top:0; bottom:0;
    width:52%;
    z-index:10;
    cursor:pointer;
    transition:transform 1.4s cubic-bezier(.77,0,.18,1), box-shadow .6s ease;
    background:
      repeating-linear-gradient(90deg,
        rgba(0,0,0,.28) 0px, rgba(0,0,0,.28) 2px,
        rgba(255,255,255,.05) 2px, rgba(255,255,255,.05) 4px,
        transparent 4px, transparent 34px),
      linear-gradient(90deg, var(--velvet-dark), var(--deep-red) 35%, var(--deep-red-2) 70%, var(--velvet-dark));
    box-shadow: inset 0 0 60px rgba(0,0,0,.55), inset 0 0 140px rgba(0,0,0,.35);
  }
  .curtain::before{ /* top swag / valance */
    content:"";
    position:absolute; top:0; left:0; right:0; height:11%;
    background:
      repeating-linear-gradient(90deg, var(--gold) 0 14px, #c79b3c 14px 28px);
    box-shadow:0 4px 10px rgba(0,0,0,.5);
    border-bottom:3px solid #8a6a22;
  }
  .curtain::after{ /* fold highlight sheen */
    content:"";
    position:absolute; inset:0;
    background:radial-gradient(ellipse 60% 40% at 50% 0%, rgba(255,255,255,.12), transparent 60%);
    mix-blend-mode:screen;
  }
  .curtain-left{ left:0; transform-origin:left center; border-radius:0 6px 6px 0; }
  .curtain-right{ right:0; transform-origin:right center; border-radius:6px 0 0 6px; }

  .theatre-wrap.opened .curtain-left{ transform:translateX(-102%) scaleX(.85) rotateY(8deg); box-shadow:20px 0 40px rgba(0,0,0,.6); }
  .theatre-wrap.opened .curtain-right{ transform:translateX(102%) scaleX(.85) rotateY(-8deg); box-shadow:-20px 0 40px rgba(0,0,0,.6); }

  .curtain-tassel{
    position:absolute; bottom:6%;
    width:26px; height:26px; border-radius:50%;
    background:radial-gradient(circle at 35% 30%, var(--gold-bright), var(--gold) 55%, #9c7423);
    box-shadow:0 0 0 4px rgba(0,0,0,.15), 0 6px 10px rgba(0,0,0,.4);
  }
  .curtain-left .curtain-tassel{ right:10%; }
  .curtain-right .curtain-tassel{ left:10%; }

  /* Center seam glow (draws eye to the click point) */
  .seam-cta{
    position:absolute; top:50%; left:50%;
    transform:translate(-50%,-50%);
    z-index:20;
    display:flex; flex-direction:column; align-items:center; gap:10px;
    pointer-events:none;
  }
  .theatre-wrap.opened .seam-cta{ display:none; }
  .ribbon-btn{
    pointer-events:auto;
    cursor:pointer;
    font-family:'Trebuchet MS', sans-serif;
    font-weight:700;
    letter-spacing:2px;
    text-transform:uppercase;
    font-size:13px;
    color:#3a2400;
    padding:14px 26px;
    border-radius:40px;
    border:2px solid #fff3cf;
    background:linear-gradient(180deg,#fff3cf,var(--gold) 60%,#c79b3c);
    box-shadow:0 8px 22px rgba(0,0,0,.45), 0 0 0 6px rgba(232,194,96,.15);
    animation:pulseBtn 2.2s ease-in-out infinite;
  }
  .ribbon-btn:hover{ filter:brightness(1.08); }
  @keyframes pulseBtn{
    0%,100%{ transform:scale(1); box-shadow:0 8px 22px rgba(0,0,0,.45), 0 0 0 6px rgba(232,194,96,.15); }
    50%{ transform:scale(1.045); box-shadow:0 10px 26px rgba(0,0,0,.5), 0 0 0 12px rgba(232,194,96,.06); }
  }
  .seam-hint{
    color:#f4e6bd;
    font-size:11.5px;
    letter-spacing:1.5px;
    font-family:'Trebuchet MS', sans-serif;
    text-transform:uppercase;
    opacity:.8;
  }

  /* ================= FOOTER INFO STRIP ================= */
  .info-strip{
    position:relative; z-index:5;
    width:min(980px,94vw);
    margin:20px auto 10px;
    display:flex; flex-wrap:wrap; gap:14px;
    justify-content:center;
  }
  .info-chip{
    background:rgba(255,255,255,.06);
    border:1px solid rgba(232,194,96,.35);
    color:#f0eedd;
    padding:10px 18px;
    border-radius:30px;
    font-family:'Trebuchet MS', sans-serif;
    font-size:12.5px;
    letter-spacing:.6px;
    display:flex; align-items:center; gap:8px;
    backdrop-filter:blur(3px);
  }
  .info-chip b{ color:var(--gold-bright); font-weight:700; }
  .dot{ width:7px;height:7px;border-radius:50%; background:var(--green); box-shadow:0 0 8px var(--green); }

  .footer-note{
    text-align:center;
    color:#8b91b8;
    font-family:'Trebuchet MS', sans-serif;
    font-size:11.5px;
    letter-spacing:1px;
    padding:26px 14px 34px;
  }
  .footer-note span{ color:var(--gold); }

  /* Confetti canvas overlays entire viewport */
  #confetti-canvas{
    position:fixed; inset:0; z-index:999; pointer-events:none;
  }

  /* Reset button */
  .reset-btn{
    position:fixed; bottom:18px; right:18px; z-index:50;
    font-family:'Trebuchet MS', sans-serif;
    font-size:11.5px; letter-spacing:1px; text-transform:uppercase;
    color:#e9e6ff; background:rgba(20,20,45,.6);
    border:1px solid rgba(232,194,96,.4);
    padding:9px 14px; border-radius:24px; cursor:pointer;
    opacity:0; transform:translateY(10px);
    transition:opacity .4s ease, transform .4s ease;
  }
  .reset-btn.show{ opacity:1; transform:translateY(0); }
  .reset-btn:hover{ background:rgba(232,194,96,.18); }

  @media (max-width:640px){
    .theatre-wrap{ aspect-ratio:9/13; border-radius:10px; }
