</style>
</head>
<body>

<canvas id="confetti-canvas"></canvas>

<div class="stage">

  <div class="sparkle-layer" id="sparkleLayer"></div>

  <!-- ===== Header ===== -->
  <div class="header">
    <div class="kicker">Digital Logo Unveiling Ceremony</div>
    <h1 class="main-title"><?php echo htmlspecialchars($eventTitle); ?></h1>
    <div class="sub-title"><?php echo htmlspecialchars($instituteName); ?></div>
    <div class="divider"></div>
  </div>

  <!-- ===== Curtain / Theatre ===== -->
  <div class="theatre-wrap" id="theatreWrap">
    <div class="spotlight"></div>

    <div class="reveal-stage">
      <div class="logo-frame">
        <div class="logo-frame-inner">
          <img src="<?php echo $logoSrc; ?>" alt="AJIET Staff Club Logo">
        </div>
      </div>
      <div class="reveal-caption">
        <div class="r-title">Officially Inaugurated Today!</div>
        <div class="r-sub"><?php echo htmlspecialchars($eventTagline); ?></div>
      </div>
    </div>

    <div class="curtain curtain-left" id="curtainLeft">
      <span class="curtain-tassel"></span>
    </div>
    <div class="curtain curtain-right" id="curtainRight">
      <span class="curtain-tassel"></span>
    </div>

    <div class="seam-cta">
      <div class="ribbon-btn" id="revealBtn">✦ Click to Inaugurate ✦</div>
      <div class="seam-hint">Tap the curtain to reveal the logo</div>
    </div>
  </div>

  <!-- ===== Info strip (PHP-driven) ===== -->
  <div class="info-strip">
    <div class="info-chip"><span class="dot"></span><b>Date:</b>&nbsp;<?php echo $dayName . ', ' . $inaugDate; ?></div>
    <div class="info-chip"><span class="dot"></span><b>Time:</b>&nbsp;<?php echo $inaugTime; ?></div>
    <div class="info-chip"><span class="dot"></span><b>Witnessed by:</b>&nbsp;<?php echo $visits; ?> guest<?php echo $visits==1?'':'s'; ?></div>
  </div>

  <div class="footer-note">
    Crafted with pride for <span><?php echo htmlspecialchars($eventTitle); ?></span> &mdash; <?php echo htmlspecialchars($eventTagline); ?>
  </div>
</div>

<div class="reset-btn" id="resetBtn">↺ Replay Ceremony</div>

<script>
(function(){
  const wrap      = document.getElementById('theatreWrap');
  const btn       = document.getElementById('revealBtn');
  const curtainL  = document.getElementById('curtainLeft');
  const curtainR  = document.getElementById('curtainRight');
  const resetBtn  = document.getElementById('resetBtn');
  const sparkleLayer = document.getElementById('sparkleLayer');

  /* ---------- ambient sparkles ---------- */
  for(let i=0;i<45;i++){
    const s = document.createElement('div');
    s.className = 'sparkle';
    s.style.left = Math.random()*100 + '%';
    s.style.top  = Math.random()*100 + '%';
    s.style.animationDelay = (Math.random()*3.5) + 's';
    sparkleLayer.appendChild(s);
  }

  /* ---------- confetti ---------- */
  const canvas = document.getElementById('confetti-canvas');
  const ctx = canvas.getContext('2d');
  function resize(){ canvas.width = innerWidth; canvas.height = innerHeight; }
  resize(); window.addEventListener('resize', resize);

  const colors = ['#e8c260','#233ea8','#1c8a4b','#e3302e','#f5b400','#ffffff'];
  let particles = [];
  let confettiRunning = false;

  function launchConfetti(){
    particles = [];
    const count = 160;
    for(let i=0;i<count;i++){
      particles.push({
        x: canvas.width/2 + (Math.random()-0.5)*300,
        y: canvas.height*0.28 + (Math.random()-0.5)*40,
        vx: (Math.random()-0.5)*9,
        vy: Math.random()*-9 - 3,
        g: 0.28 + Math.random()*0.12,
        size: 5 + Math.random()*6,
        color: colors[Math.floor(Math.random()*colors.length)],
        rot: Math.random()*360,
        vr: (Math.random()-0.5)*14,
        shape: Math.random() > 0.5 ? 'rect' : 'circle',
        life: 0
      });
    }
    confettiRunning = true;
    requestAnimationFrame(tick);
  }

  function tick(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    let alive = false;
    particles.forEach(p=>{
      p.vy += p.g;
      p.x += p.vx;
      p.y += p.vy;
      p.rot += p.vr;
      p.life++;
      if(p.y < canvas.height + 40 && p.life < 480){
        alive = true;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot * Math.PI/180);
        ctx.fillStyle = p.color;
        if(p.shape === 'rect'){
          ctx.fillRect(-p.size/2, -p.size/3, p.size, p.size*0.6);
        } else {
          ctx.beginPath();
          ctx.arc(0,0,p.size/2,0,Math.PI*2);
          ctx.fill();
        }
        ctx.restore();
      }
    });
    if(alive && confettiRunning){
      requestAnimationFrame(tick);
    } else {
      confettiRunning = false;
      ctx.clearRect(0,0,canvas.width,canvas.height);
    }
  }

  /* ---------- reveal logic ---------- */
  function openCurtain(){
    if(wrap.classList.contains('opened')) return;
    wrap.classList.add('opened');
    launchConfetti();
    setTimeout(()=> resetBtn.classList.add('show'), 900);
  }

  function closeCurtain(){
    wrap.classList.remove('opened');
    resetBtn.classList.remove('show');
  }

  btn.addEventListener('click', openCurtain);
  curtainL.addEventListener('click', openCurtain);
  curtainR.addEventListener('click', openCurtain);
  resetBtn.addEventListener('click', closeCurtain);
})();
</script>

</body>
</html>